diff --git a/.lore/dod.md b/.lore/dod.md
new file mode 100644
index 0000000..d881738
--- /dev/null
+++ b/.lore/dod.md
@@ -0,0 +1,21 @@
+# Definition of Done
+
+> `beforeSession` is awaited before the `try` block opens, so a throw from it escapes before the `catch` and `finally` exist. Neither `onError` nor `afterSession` runs.
+
+**Strategy: `direct`** — The chat orchestrator acts as a seam, allowing us to install hooks through configuration and observe their execution when `beforeSession` throws.
+
+## Done when these pass
+
+- [ ] **runs onError and afterSession when beforeSession throws** — pins that a thrown error in `beforeSession` propagates to the caller while invoking both `onError` and `afterSession` hooks.
+      `src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts`
+
+## Facets
+
+- [ ] Move `beforeSession` inside the `try` block in `chatOrchestrator.ts`.
+- [ ] Update `specs/hal-engine-config-hooks/spec.md` with the new guarantee for `beforeSession`.
+- [ ] Document in the CHANGELOG what changes for an existing consumer.
+
+## Out of scope
+
+- the `instanceof Error` gate on `onError` (its own issue)
+- usage accounting across tool rounds (HALEngine#93)
diff --git a/specs/hal-engine-config-hooks/spec.md b/specs/hal-engine-config-hooks/spec.md
index 5f08b31..4e4197c 100644
--- a/specs/hal-engine-config-hooks/spec.md
+++ b/specs/hal-engine-config-hooks/spec.md
@@ -23,6 +23,6 @@

 These three properties of `src/orchestration/chatOrchestrator.ts` are recorded so the hook features that follow specify against real behaviour. This issue changes none of them; each is a separate, out-of-scope change owned by no issue in this epic.

-- `beforeSession` is awaited before the `try` block opens ([chatOrchestrator.ts#L91](../../src/orchestration/chatOrchestrator.ts#L91)), so a throw there escapes before the `catch`/`finally` exist and skips both `onError` and `afterSession`.
+- `beforeSession` is inside the `try` block, so a throw there reaches the `catch`/`finally` blocks, firing both `onError` and `afterSession`, where a deployer can assume no tools were run and the turn was aborted before provider interaction ([validated by: runs onError and afterSession when beforeSession throws](../../src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts#L40)).
 - The `catch` gates `onError` on `error instanceof Error` ([chatOrchestrator.ts#L150](../../src/orchestration/chatOrchestrator.ts#L150)), so a rejection that is not an `Error` — a thrown string or object — bypasses `onError` entirely while still propagating to the caller.
 - `afterModelResponse` is called once per user message after the round loop exits ([chatOrchestrator.ts#L148](../../src/orchestration/chatOrchestrator.ts#L148)), and is passed the `lastUsage` local — the most recent round's usage, not a sum across tool rounds, so a deployer using the hook for billing or audit under-counts every turn that ran tools.
diff --git a/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts b/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts
new file mode 100644
index 0000000..7c4797f
--- /dev/null
+++ b/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts
@@ -0,0 +1,67 @@
+import {describe, expect, it} from '@jest/globals';
+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+
+function createSession(content: string): ChatSession {
+  return {
+    sessionId: 's1',
+    userId: 'u1',
+    entries: [{role: 'user', content, timestamp: SENT_AT}],
+  };
+}
+
+function createMockProvider(response: string): AIProvider {
+  return {
+    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
+      yield {type: 'text', text: response};
+      yield {type: 'stop', stopReason: 'end_turn'};
+    },
+    async generateStructured<T>(): Promise<T> {
+      return {} as T;
+    },
+  };
+}
+
+const promptBuilder = new PromptBuilder({
+  baseSystemPrompt: 'You are HAL.',
+  systemPromptSuffix: 'Be precise.',
+  contextConfig: {
+    historyLength: 10,
+    includeTimestamps: false,
+    includeSystemPrompt: true,
+  },
+});
+
+describe('beforeSession throwing', () => {
+  it('runs onError and afterSession when beforeSession throws', async () => {
+    const errorToThrow = new Error('Database connection failed in beforeSession');
+
+    let caughtError: Error | undefined;
+    let afterSessionRan = false;
+
+    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
+      hooks: {
+        beforeSession: async () => {
+          throw errorToThrow;
+        },
+        onError: async (_session, error) => {
+          caughtError = error;
+        },
+        afterSession: async () => {
+          afterSessionRan = true;
+        },
+      },
+    });
+
+    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow(
+      'Database connection failed in beforeSession'
+    );
+
+    expect(caughtError).toBe(errorToThrow);
+    expect(afterSessionRan).toBe(true);
+  });
+});

